        if (row < N && (kk + threadIdx.x) < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + (kk + threadIdx.x)];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if ((kk + threadIdx.y) < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[(kk + threadIdx.y) * N + col];
