    const int UNROLL_FACTOR = 4;
    const int TILE_SIZE = 32;

    for (int kk = 0; kk < N; kk += TILE_SIZE) {
        // Load tiles into shared memory with coalesced access
        int k_index = kk + threadIdx.x;
        if (row < N && k_index < N) {
