#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[16][16];
    __shared__ float Bs[16][16];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x * 16;
    int by = blockIdx.y * 16;

    // Each thread computes one element
    int row = by + ty;
    int col = bx + tx;

    float sum = 0.0f;

    for (int kk = 0; kk < N; kk += 16) {
        // Load tiles into shared memory with vectorized access
        if (row < N && (kk + tx) < N) {
            As[ty][tx] = A[row * N + (kk + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((kk + ty) < N && col < N) {
            Bs[ty][tx] = B[(kk + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product with loop unrolling
        #pragma unroll
        for (int k = 0; k < 16; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

